f@m = clamp(@P.y / (0.12 * height), 0, 1);
const cx = Math.abs(@P.x) / (width / 2), cz = Math.abs(@P.z) / (depth / 2), k = 1 - 0.2 * Math.pow(cx * cz, 2);
@P.x *= k; @P.z *= k;

const H = height, n = Math.max(0, Math.round(strata)), s = Math.min(width, depth);
f@band = 0.5;
if (n > 0) {
  const t = @P.y / H * n + 0.3 * noise([@P.x * 0.35, 0, @P.z * 0.35], seed), k = Math.floor(t), f = t - k;
  const off = ((rand(k, seed) - 0.5) * 0.14 + (f - 0.5) * 0.06) * s * (0.4 + roughness) * @m;
  const d = [@P.x / width, 0, @P.z / depth], l = Math.hypot(d[0], d[2]);
  if (l > 1e-6) @P = add(@P, mul(d, off / l));
  f@band = rand(k, seed, 7);
}
if (@m <= 0) @P.y = 0;
